  if(form.endsWith('する')){const noun=form.slice(0,-2),parts=words.filter(w=>w.s===noun);if(parts.length&&parts.every(w=>w.k===parts[0].k))return parts[0].k+'する';}
  return DATA.formReadings?.[form]||'';
